const RULES = [   // teksty z liczbami, które przychodzą z silnika
  [/^Runda (\d+): agent pracuje\.$/, 'Round $1: the agent is working.'], [/^Runda (\d+): sprawdzam wynik\.$/, 'Round $1: checking the result.'], [/^Runda (\d+): pyta agenta (.+)\.$/, 'Round $1: asking agent $2.'],
  [/^Agent niedostępny\. Ponowna próba za (\d+) min\.$/, 'Agent unavailable. Retrying in $1 min.'],
  [/^Limit 5 godzin na (\d+)%\. Czekam na odnowienie o (\S+)\.$/, '5-hour limit at $1%. Waiting for the reset at $2.'],
];
let LANG = 'pl';
try{ LANG = localStorage.getItem('lumobot-lang') || 'pl'; }catch(e){}
function tr(s){
  if(LANG !== 'en' || s == null) return s;
  if(EN[s] !== undefined) return EN[s];
  for(const [re, to] of RULES) if(re.test(s)) return String(s).replace(re, to);
  return s;
}
const ORIG = new WeakMap(), ATTRS = ['placeholder', 'title', 'aria-label'];
function translateStatic(){   // teksty wpisane na stałe w stronie; dynamiczne przechodzą przez tr() przy rysowaniu
  const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  for(let n = walk.nextNode(); n; n = walk.nextNode()){
    if(n.parentElement.closest('script,style,[data-keep],#chat,#agents')) continue;
    if(!ORIG.has(n)){ const t = n.nodeValue.trim(); if(!t || EN[t] === undefined) continue; ORIG.set(n, n.nodeValue); }
    const pl = ORIG.get(n); n.nodeValue = LANG === 'en' ? pl.replace(pl.trim(), EN[pl.trim()]) : pl;
  }
  document.querySelectorAll('[placeholder],[title],[aria-label]').forEach(el => { for(const a of ATTRS){ if(!el.hasAttribute(a)) continue;
    const key = 'pl' + a.replace('-', ''); if(el.dataset[key] === undefined){ if(EN[el.getAttribute(a)] === undefined) continue; el.dataset[key] = el.getAttribute(a); }
    el.setAttribute(a, LANG === 'en' ? EN[el.dataset[key]] : el.dataset[key]); } });
  document.documentElement.lang = LANG;
}
function setLang(l){ LANG = l === 'en' ? 'en' : 'pl'; try{ localStorage.setItem('lumobot-lang', LANG); }catch(e){} translateStatic(); }
document.addEventListener('DOMContentLoaded', translateStatic);
